import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const manifest = await readFile(join(root, "sdk-runtime", "package.json"), "utf8");
const lock = await readFile(join(root, "sdk-runtime", "package-lock.json"), "utf8");
const escape = (text) => text.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
const ts =
  "// Generated by scripts/build-sdk-runtime.mjs - do not edit by hand.\n" +
  `export const SDK_RUNTIME_MANIFEST = \`${escape(manifest)}\`;\n` +
  `export const SDK_RUNTIME_LOCK = \`${escape(lock)}\`;\n`;
await writeFile(join(root, "server", "sdk-runtime.generated.ts"), ts);
console.log(`sdk-runtime.generated.ts: ${ts.length} bytes`);
